@IsTest
private class HelpDeskServiceTest {
    @IsTest static void emptyReturnsZero() {
        System.assertEquals(0, HelpDeskService.openCount());
    }
    @IsTest static void mixedStatusesCountOnlyOpen() {
        insert new List<Help_Request__c>{
            new Help_Request__c(Subject__c='Fictional projector', Status__c='New',
                Category__c='Hardware', Priority__c='Medium'),
            new Help_Request__c(Subject__c='Fictional repair', Status__c='Closed',
                Category__c='Hardware', Priority__c='Medium', Resolution_Notes__c='Fixed')
        };
        Test.startTest();
        Integer actual = HelpDeskService.openCount();
        Test.stopTest();
        System.assertEquals(1, actual);
    }
    @IsTest static void bulkReturnsTwoHundred() {
        List<Help_Request__c> requests = new List<Help_Request__c>();
        for (Integer i=0; i<200; i++) {
            requests.add(new Help_Request__c(Subject__c='Fictional ticket '+i,
                Status__c='New', Category__c='Hardware', Priority__c='Medium'));
        }
        insert requests;
        Test.startTest();
        Integer actual = HelpDeskService.openCount();
        Test.stopTest();
        System.assertEquals(200, actual);
    }
    @IsTest static void closingWithoutNotesIsRejected() {
        Help_Request__c request = new Help_Request__c(Subject__c='Fictional ticket',
            Status__c='Closed', Category__c='Hardware', Priority__c='Medium');
        Database.SaveResult result = Database.insert(request, false);
        System.assertEquals(false, result.isSuccess());
        System.assertEquals(StatusCode.FIELD_CUSTOM_VALIDATION_EXCEPTION,
            result.getErrors()[0].getStatusCode());
    }
}

import { LightningElement, wire } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import openCount from '@salesforce/apex/HelpDeskService.openCount';
export default class HelpDeskCount extends LightningElement {
    count;
    error;
    wiredResult;
    refreshing = false;
    get hasCount() { return this.count !== undefined; }
    @wire(openCount)
    receiveCount(result) {
        this.wiredResult = result;
        const { data, error } = result;
        if (data !== undefined) { this.count = data; this.error = undefined; }
        else if (error) { this.count = undefined; this.error = 'Cannot load. Check app permissions.'; }
    }
    async refreshCount() {
        if (!this.wiredResult) return;
        this.refreshing = true;
        try { await refreshApex(this.wiredResult); }
        catch { this.count = undefined; this.error = 'Refresh failed. Please retry.'; }
        finally { this.refreshing = false; }
    }
}
